using PlcMcp.Core.Workspaces;
using PlcMcp.EngineeringService.Exchange;
using PlcMcp.Inovance;
using Xunit;

namespace PlcMcp.Tests;

public sealed class GraphCompatibilityTests
{
    // Captured from the independently downloaded rc.2 release, not regenerated by current code.
    [Theory]
    [InlineData("fbd-v2-data", "3acdd51d044218ccb1ef46f4a489dbf8fe83477ad0111973c782f323525458bc")]
    [InlineData("fbd-v2-function", "ed2a2540e0e0f394a7f160de991647f700ad249c75771a80d515bf2ed6f78bf3")]
    [InlineData("fbd-v2-initializers", "b4bef421079b28cf2d01f4cb2e420ef06d697dcd72a66233954cd26b5b1f1ca0")]
    [InlineData("ld-v2-initializers", "7c1616f56aa06ec80c90f64db6749fc35bdd8cb352725677101bc9d889b12b40")]
    [InlineData("ld-v2-motor", "1d9bd8b9b683bf5f4ac601a53fb4a983a01691026592e81e14d556bbc6476e83")]
    [InlineData("sfc-v2-branches", "e200b66c3479cdb9b0df4d878b3e636352e24e9c51eca84d0ceca1918931647c")]
    [InlineData("sfc-v2-initializers", "46a10af7400010ba5ffa1ba6ea92296b4427496ff14217deffeb3dffda9f5386")]
    [InlineData("sfc-v2-timed", "e695f4bcc8ffa959fa45123ac07fa6f27194776ff6b6a94de04e99b048d9c05f")]
    public void Existing_v2_documents_keep_rc2_semantic_hashes(string file, string hash)
    {
        var p = ExchangeTests.Sample(file);
        Assert.Equal(hash, PlcOpenGraphCodec.SemanticHash(p));
        Assert.Equal(hash, PlcOpenGraphCodec.Decode(PlcOpenGraphCodec.Encode(p)).SemanticSha256);
    }
    [Theory][InlineData("ld-v2-declarations")][InlineData("fbd-v2-declarations")][InlineData("sfc-v2-multi-actions")]
    public void Complete_example_graphs_roundtrip_with_target_preflight(string file)
    {
        var p = ExchangeTests.Sample(file); Assert.Null(GraphRules.Validate(p)); Assert.Null(new InovanceGraphPolicy().Validate(p));
        Assert.Equal(PlcOpenGraphCodec.SemanticHash(p), PlcOpenGraphCodec.Decode(PlcOpenGraphCodec.Encode(p)).SemanticSha256);
    }
}
